import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";

const Results = () => {
  const location = useLocation();
  const query = location.state?.query;

  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  // ✅ Fetch Data from SerpAPI
  useEffect(() => {
    if (!query) return;

    const fetchProducts = async () => {
      try {
        const apiKey = process.env.REACT_APP_SERP_API_KEY;

        const response = await fetch(
          `https://serpapi.com/search.json?engine=google_shopping&q=${query}+Pakistan&api_key=${apiKey}`
        );

        const data = await response.json();

        const results = data.shopping_results || [];

        // ✅ Sirf 4 products
        const formatted = results.slice(0, 4).map((item) => ({
          title: item.title,
          price: item.price,
          rating: item.rating,
          image: item.thumbnail,
          link: item.link,
          source: item.source,
        }));

        setProducts(formatted);
        setLoading(false);

      } catch (error) {
        console.error("Error:", error);
        setLoading(false);
      }
    };

    fetchProducts();
  }, [query]);

  // ✅ Add to Favorite
  const addToFavorite = (product) => {
    let favs = JSON.parse(localStorage.getItem("favorites")) || [];

    favs.push(product);

    localStorage.setItem("favorites", JSON.stringify(favs));

    alert("Added to favorites!");
  };

  return (
    <>
      <Header />

      <div style={{ padding: "30px" }}>
        <h2>Results</h2>
        <p><strong>Search:</strong> {query}</p>

        {loading ? (
          <p>Loading...</p>
        ) : (
          products.map((item, index) => (
            <div
              key={index}
              style={{
                border: "1px solid #ddd",
                padding: "15px",
                marginBottom: "20px",
                borderRadius: "10px"
              }}
            >
              {/* Image */}
              <img
                src={item.image}
                alt="product"
                style={{ width: "150px" }}
              />

              {/* Title */}
              <h3>{item.title}</h3>

              {/* Price */}
              <p><strong>Price:</strong> {item.price || "N/A"}</p>

              {/* Rating */}
              <p><strong>Rating:</strong> {item.rating || "N/A"}</p>

              {/* Source */}
              <p><strong>Website:</strong> {item.source}</p>

              {/* Buttons */}
              <button onClick={() => addToFavorite(item)}>
                Add to Favorite
              </button>

              <a
                href={item.link}
                target="_blank"
                rel="noopener noreferrer"
                style={{ marginLeft: "10px" }}
              >
                <button>Go to Website</button>
              </a>
            </div>
          ))
        )}
      </div>

      <Footer />
    </>
  );
};

export default Results;
